for n,eq,ans,k,e in [(1,r'y^{\prime}+x\sqrt y=x^2','nonlinear','미지함수의 제곱근이 들어가 선형이 아니다.','The square root of the unknown makes the equation nonlinear.'),(2,r'y^{\prime}-x=y\tan x',r'y^{\prime}-(\tan x)y=x','미지함수와 그 도함수가 일차이다.','The unknown and its derivative occur to the first power.'),(3,r'ue^t=t+\sqrt t\,u^{\prime}',r'u^{\prime}-\frac{e^t}{\sqrt t}u=-\sqrt t,\quad t>0','양의 시간에서 도함수의 계수로 나누면 표준형이 된다.','At positive time division by the derivative coefficient gives standard form.'),(4,r'R^{\prime}+t\cos R=e^{-t}','nonlinear','미지함수가 코사인 안에 들어가 선형이 아니다.','The cosine of the unknown makes the equation nonlinear.')]:
 add(n,M(eq)+'의 선형성을 판정하고 선형이면 표준형으로 쓰라.','Classify linearity of '+M(eq)+' and give standard form if linear.',[(k,e),('계수는 독립변수에만 의존해야 한다.','Coefficients may depend only on the independent variable.')],('비선형.' if ans=='nonlinear' else '선형: '+M(ans)),('Nonlinear.' if ans=='nonlinear' else 'Linear: '+M(ans)),'미지함수의 비선형 거듭제곱이나 함수 합성이 있는지 검사했다.','Checked for nonlinear powers or function compositions of the unknown.')
rows=[
(5,r'y^{\prime}+y=1',r'e^x',r'(e^xy)^{\prime}=e^x',r'y=1+Ce^{-x}','모든 실수에서 정의된다.','Defined on the whole real line.'),
(6,r'y^{\prime}-y=e^x',r'e^{-x}',r'(e^{-x}y)^{\prime}=1',r'y=(x+C)e^x','모든 실수에서 정의된다.','Defined on the whole real line.'),
(7,r'y^{\prime}=x-y',r'e^x',r'(e^xy)^{\prime}=xe^x',r'y=x-1+Ce^{-x}','부분적분으로 입력 곱 지수함수를 적분한다.','Integration by parts handles the input times the exponential.'),
(8,r'4x^3y+x^4y^{\prime}=\sin^3x',r'x^4',r'(x^4y)^{\prime}=\sin^3x',r'y=\frac{-\cos x+\frac13\cos^3x+C}{x^4},\quad x\ne0','분자의 적분상수 삼분의 이인 가지는 영에서 값 사분의 일로 매끄럽게 연장된다.','The branch with constant two thirds extends smoothly at zero with value one quarter.'),
(9,r'xy^{\prime}+y=\sqrt x',r'x',r'(xy)^{\prime}=\sqrt x',r'y=\frac23\sqrt x+\frac Cx,\quad x>0','실수 근호와 표준형이 양의 입력 구간을 요구한다.','The real radical and standard form require positive input.'),
(10,r'2xy^{\prime}+y=2\sqrt x',r'\sqrt x',r'(\sqrt x\,y)^{\prime}=1',r'y=\sqrt x+C/\sqrt x,\quad x>0','도함수의 계수를 먼저 나누고 적분인자를 적용한다.','Divide by the derivative coefficient before applying the factor.'),
(11,r'xy^{\prime}-2y=x^2,\quad x>0',r'x^{-2}',r'(y/x^2)^{\prime}=1/x',r'y=x^2(\ln x+C)','양의 입력 조건 때문에 로그에 절댓값이 필요 없다.','Positive input removes the need for an absolute value in the logarithm.'),
(12,r'y^{\prime}-3x^2y=x^2',r'e^{-x^3}',r'(e^{-x^3}y)^{\prime}=x^2e^{-x^3}',r'y=-1/3+Ce^{x^3}','상수해도 임의 상수 영으로 포함된다.','The constant solution is included by a zero arbitrary coefficient.'),
(13,r't^2y^{\prime}+3ty=\sqrt{1+t^2},\quad t>0',r't^3',r'(t^3y)^{\prime}=t\sqrt{1+t^2}',r'y=\frac{(1+t^2)^{3/2}/3+C}{t^3}','일 더하기 시간 제곱을 치환해 적분한다.','Substitute one plus time squared in the integral.'),
(14,r't\ln t\,r^{\prime}+r=te^t',r'\ln t',r'((\ln t)r)^{\prime}=e^t',r'r=\frac{e^t+C}{\ln t},\quad t>0,\ t\ne1','상수 음의 자연상수인 가지는 시간 일에서 값 자연상수로 연장되며 원래 식도 만족한다.','The branch with constant minus Euler’s number extends at time one with value Euler’s number and satisfies the original equation.'),
(15,r'y^{\prime}+y\cos x=x',r'e^{\sin x}',r'(e^{\sin x}y)^{\prime}=xe^{\sin x}',r'y=e^{-\sin x}\left(C+\int_0^xte^{\sin t}\,dt\right)','초등함수 원시함수가 없어도 정적분 표현은 정확한 해이다.','The definite-integral expression is exact even without an elementary antiderivative.'),
(16,r'y^{\prime}+2xy=x^3e^{x^2}',r'e^{x^2}',r'(e^{x^2}y)^{\prime}=x^3e^{2x^2}',r'y=\frac{2x^2-1}{8}e^{x^2}+Ce^{-x^2}','치환 후 부분적분으로 우변을 적분한다.','Substitution followed by integration by parts evaluates the right side.'),
(17,r'xy^{\prime}+y=3x^2,\ y(1)=4',r'x',r'xy=x^3+C,\quad C=3',r'y=x^2+3/x,\quad x>0','초기점을 포함하는 최대 구간은 양의 입력이다.','The maximal interval through the initial point is positive input.'),
(18,r'xy^{\prime}-2y=2x,\ y(2)=0',r'x^{-2}',r'y/x^2=-2/x+C,\quad C=1',r'y=x^2-2x','원래 나눠지지 않은 식에는 입력 영에서도 해가 매끄럽게 연장된다.','The solution extends smoothly through zero in the original undivided equation.'),
(19,r'x^2y^{\prime}+2xy=\ln x,\ y(1)=2',r'x^2',r'x^2y=x\ln x-x+C,\quad C=3',r'y=(x\ln x-x+3)/x^2,\quad x>0','로그가 양의 입력을 요구한다.','The logarithm requires positive input.'),
(20,r't^3y^{\prime}+3t^2y=\cos t,\ y(\pi)=0',r't^3',r't^3y=\sin t+C,\quad C=0',r'y=\sin t/t^3,\quad t>0','원래 초기점을 포함하는 구간에서 분모가 영인 시점을 제외한다.','Exclude the denominator zero on the interval containing the initial point.'),
(21,r'tu^{\prime}=t^2+3u,\quad t>0,\quad u(2)=4',r't^{-3}',r'u/t^3=-1/t+C,\quad C=1',r'u=t^3-t^2,\quad t>0','문제에 주어진 양의 시간 조건을 유지한다.','Retain the stated positive-time condition.'),
(22,r'xy^{\prime}+y=x\ln x,\ y(1)=0',r'x',r'xy=\tfrac12x^2\ln x-\tfrac14x^2+C,\quad C=1/4',r'y=\tfrac12x\ln x-\tfrac14x+1/(4x),\quad x>0','초기점에서 로그 항과 두 나머지 항이 정확히 상쇄된다.','At the initial point the logarithm vanishes and the remaining terms cancel.'),
(23,r'xy^{\prime}=y+x^2\sin x,\ y(\pi)=0',r'x^{-1}',r'y/x=-\cos x+C,\quad C=-1',r'y=-x(1+\cos x)','원래 식에서는 입력 영까지 매끄럽게 연장되는 가지이다.','This branch extends smoothly through zero in the original equation.'),
(24,r'(x^2+1)y^{\prime}+3x(y-1)=0,\ y(0)=2',r'(1+x^2)^{3/2}',r'[(1+x^2)^{3/2}(y-1)]^{\prime}=0',r'y=1+(1+x^2)^{-3/2}','분모가 항상 양수이므로 모든 실수에서 해가 정의된다.','The denominator is always positive, giving a global real solution.')]
